    /* 0x010 */ short nTargetX; // Target tile X
    /* 0x012 */ short nTargetY; // Target tile Y
    /* 0x014 */ short nPrevTargetX; // Previous target tile X
    /* 0x016 */ short nPrevTargetY; // Previous target tile Y
    /* 0x018 */ short nSavedTargetX; // Saved/final target tile X
    /* 0x01A */ short nSavedTargetY; // Saved/final target tile Y
